-- Synthetic hospital. Every row is generated by SeedRunner; nothing here is real.

CREATE TABLE department (
    id    NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code  VARCHAR2(16) NOT NULL,
    name  VARCHAR2(80) NOT NULL,
    CONSTRAINT uq_department_code UNIQUE (code)
);

CREATE TABLE staff (
    id             NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    department_id  NUMBER        NOT NULL,
    full_name      VARCHAR2(120) NOT NULL,
    role           VARCHAR2(20)  NOT NULL,
    email          VARCHAR2(120) NOT NULL,
    salary_mad     NUMBER(10,2)  NOT NULL,
    hired_on       DATE          NOT NULL,
    CONSTRAINT fk_staff_department FOREIGN KEY (department_id) REFERENCES department (id),
    CONSTRAINT ck_staff_role CHECK (role IN ('DOCTOR', 'NURSE', 'RECEPTIONIST', 'HR', 'ADMIN')),
    CONSTRAINT uq_staff_email UNIQUE (email)
);

CREATE TABLE patient (
    id             NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    department_id  NUMBER        NOT NULL,
    doctor_id      NUMBER        NOT NULL,
    full_name      VARCHAR2(120) NOT NULL,
    national_id    VARCHAR2(12)  NOT NULL,
    birth_date     DATE          NOT NULL,
    phone          VARCHAR2(20)  NOT NULL,
    address        VARCHAR2(200) NOT NULL,
    diagnosis      VARCHAR2(200) NOT NULL,
    admitted_on    DATE          NOT NULL,
    CONSTRAINT fk_patient_department FOREIGN KEY (department_id) REFERENCES department (id),
    CONSTRAINT fk_patient_doctor FOREIGN KEY (doctor_id) REFERENCES staff (id),
    CONSTRAINT uq_patient_national_id UNIQUE (national_id)
);
CREATE INDEX ix_patient_department ON patient (department_id);
CREATE INDEX ix_patient_doctor ON patient (doctor_id);

CREATE TABLE appointment (
    id             NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    patient_id     NUMBER        NOT NULL,
    doctor_id      NUMBER        NOT NULL,
    department_id  NUMBER        NOT NULL,
    scheduled_at   TIMESTAMP     NOT NULL,
    status         VARCHAR2(12)  NOT NULL,
    notes          VARCHAR2(300),
    CONSTRAINT fk_appointment_patient FOREIGN KEY (patient_id) REFERENCES patient (id),
    CONSTRAINT fk_appointment_doctor FOREIGN KEY (doctor_id) REFERENCES staff (id),
    CONSTRAINT fk_appointment_department FOREIGN KEY (department_id) REFERENCES department (id),
    CONSTRAINT ck_appointment_status CHECK (status IN ('SCHEDULED', 'DONE', 'CANCELLED'))
);
CREATE INDEX ix_appointment_dept_day ON appointment (department_id, scheduled_at);

CREATE TABLE document (
    id             NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    department_id  NUMBER        NOT NULL,
    title          VARCHAR2(160) NOT NULL,
    body           CLOB          NOT NULL,
    uploaded_on    DATE          NOT NULL,
    CONSTRAINT fk_document_department FOREIGN KEY (department_id) REFERENCES department (id)
);
